// Sounds. The speaker and the mic share the codec, so the recorder task, which owns the mic,
// is the only place either is started.
enum class Sound : uint8_t { None, Listen, Sent, Replied, Error };

static void play_tones(Sound s) {
  M5.Speaker.begin();
  M5.Speaker.setVolume(SPEAKER_VOLUME);
  auto tone = [](float hz, uint32_t ms) {
    M5.Speaker.tone(hz, ms);
    while (M5.Speaker.isPlaying()) vTaskDelay(1);
  };
  switch (s) {
    case Sound::Listen: tone(2600, 14); break;
    case Sound::Sent: tone(1800, 12); vTaskDelay(70); tone(1800, 12); break;
    case Sound::Replied: tone(1200, 40); tone(1800, 60); break;
    case Sound::Error: tone(380, 90); break;
    case Sound::None: break;
  }
  M5.Speaker.end();
}

// Recorder: one task owns button A, the mic and the speaker, so a blocking network call in loop()
// can never drop audio or miss the release.
struct Recorder {
  int16_t* buf = nullptr;
  std::atomic<bool> armed{true};
  std::atomic<bool> active{false};
  std::atomic<bool> finished{true};
  std::atomic<bool> capped{false};
  std::atomic<bool> cancel_req{false};
  std::atomic<bool> cancelled{false};
  std::atomic<uint32_t> seq{0};
  std::atomic<size_t> done_bytes{0};
  std::atomic<uint32_t> press_ms{0};
  std::atomic<uint32_t> release_ms{0};
  std::atomic<uint32_t> sim_until_ms{0};
  std::atomic<uint8_t> sound{(uint8_t)Sound::None};
  size_t queued_chunks = 0;
  bool mic_on = false;
};
static Recorder rec;

static void request_sound(Sound s) {
  if (rtc_sound_on) rec.sound.store((uint8_t)s);
}

static void recorder_task(void*) {
  bool stable = false;
  bool last_raw = false;
  uint32_t last_change = 0;
  for (;;) {
    uint32_t now = millis();
    uint32_t sim_until = rec.sim_until_ms.load();
    bool sim = sim_until && (int32_t)(sim_until - now) > 0;
    if (sim_until && !sim) rec.sim_until_ms.store(0);
    bool raw = gpio_get_level(PTT_PIN) == PRESSED_LEVEL || sim;
    if (raw != last_raw) { last_raw = raw; last_change = now; }
    bool pressed = stable;
    if (raw != stable && (sim || now - last_change >= DEBOUNCE_MS)) pressed = raw;

    if (pressed && !stable && rec.armed.load() && !rec.active.load()) {
      // No click here: the speaker needs the codec, and restarting the mic after it loses about 0.9 s of speech.
      if (!rec.mic_on) rec.mic_on = M5.Mic.begin();
      rec.queued_chunks = 0;
      rec.done_bytes.store(0);
      rec.capped.store(false);
      rec.cancel_req.store(false);
      rec.cancelled.store(false);
      rec.finished.store(false);
      rec.press_ms.store(now);
      rec.release_ms.store(0);
      rec.active.store(true);
      rec.seq.fetch_add(1);
    }
    if (rec.active.load()) {
      bool over_cap = now - rec.press_ms.load() >= MAX_RECORD_MS;
      bool cancel = rec.cancel_req.exchange(false);
      if (!pressed || over_cap || cancel) {
        rec.capped.store(over_cap && pressed && !cancel);
        rec.cancelled.store(cancel);
        rec.release_ms.store(now);
        rec.active.store(false);
      } else if (rec.queued_chunks < MAX_CHUNKS && M5.Mic.isRecording() < 2) {
        if (M5.Mic.record(rec.buf + rec.queued_chunks * CHUNK_SAMPLES, CHUNK_SAMPLES, SAMPLE_RATE)) {
          rec.queued_chunks++;
        }
      }
    }
    if (!rec.finished.load()) {
      size_t in_flight = M5.Mic.isRecording();
      rec.done_bytes.store((rec.queued_chunks - in_flight) * CHUNK_BYTES);
      if (!rec.active.load() && in_flight == 0) {
        rec.finished.store(true);
      }
    }
    Sound s = (Sound)rec.sound.load();
    if (s != Sound::None && rec.finished.load() && !rec.active.load()) {
      rec.sound.store((uint8_t)Sound::None);
      if (rec.mic_on) { M5.Mic.end(); rec.mic_on = false; }
      play_tones(s);
    }
    // The mic stays running while the stick is awake, so a press records at once.
    if (!rec.mic_on && rec.finished.load() && !rec.active.load()) rec.mic_on = M5.Mic.begin();
    stable = pressed;
    vTaskDelay(1);
  }
}

// Reply text: the daemon sends UTF-8 with newlines escaped as "\n"; the display font is ASCII.
static String sanitize_reply(const String& in, size_t max = REPLY_MAX) {
  String out;
  out.reserve(in.length());
  for (size_t i = 0; i < in.length() && out.length() < max; i++) {
    uint8_t c = in[i];
    if (c == '\\' && i + 1 < in.length() && in[i + 1] == 'n') { out += '\n'; i++; continue; }
    if (c < 0x80) { if (c >= 0x20) out += (char)c; continue; }
    uint32_t cp = 0;
    int extra = c >= 0xF0 ? 3 : c >= 0xE0 ? 2 : c >= 0xC0 ? 1 : 0;
    cp = c & (0x3F >> extra);
    for (int k = 0; k < extra && i + 1 < in.length(); k++) cp = (cp << 6) | (in[++i] & 0x3F);
    switch (cp) {
      case 0x2018: case 0x2019: out += '\''; break;
      case 0x201C: case 0x201D: out += '"'; break;
      case 0x2013: case 0x2014: out += '-'; break;
      case 0x2026: out += "..."; break;
      case 0x00A0: out += ' '; break;
      default: out += '?'; break;
    }
  }
  if (out.length() > max) out.remove(max);
  return out;
}

static void copy_str(char* dst, size_t cap, const String& s) {
  strncpy(dst, s.c_str(), cap - 1);
  dst[cap - 1] = 0;
}

// Diagnostics ring: failures the stick saw while nobody watched the serial port, uploaded as `L` on the next
// watch connection.
static SemaphoreHandle_t diag_mtx;

static void diag(const char* fmt, ...) {
  char msg[160];
  va_list ap;
  va_start(ap, fmt);
  vsnprintf(msg, sizeof msg, fmt, ap);
  va_end(ap);
  char line[200];
  int n = snprintf(line, sizeof line, "b%lu t%.1fs %s\n", (unsigned long)rtc_boot_count, millis() / 1000.0f, msg);
  if (n <= 0) return;
  size_t len = (size_t)n < sizeof line ? (size_t)n : sizeof line - 1;
  Serial.printf("[%lu] diag %s", millis(), line);
  xSemaphoreTake(diag_mtx, portMAX_DELAY);
  while (rtc_diag_len && rtc_diag_len + len > DIAG_MAX) {
    const char* nl = (const char*)memchr(rtc_diag, '\n', rtc_diag_len);
    size_t drop = nl ? (size_t)(nl - rtc_diag) + 1 : rtc_diag_len;
    memmove(rtc_diag, rtc_diag + drop, rtc_diag_len - drop);
    rtc_diag_len -= drop;
  }
  if (len <= DIAG_MAX) {
    memcpy(rtc_diag + rtc_diag_len, line, len);
    rtc_diag_len += len;
  }
  xSemaphoreGive(diag_mtx);
}

static size_t diag_take(char* out) {
  xSemaphoreTake(diag_mtx, portMAX_DELAY);
  size_t n = rtc_diag_len;
  memcpy(out, rtc_diag, n);
  rtc_diag_len = 0;
  xSemaphoreGive(diag_mtx);
  return n;
}

// State shared between the network task (writer) and the main loop (reader). One mutex guards it and the inbox.
enum class LinkState : uint8_t { Joining, NoWifi, Searching, Unreachable, Up };
enum class OtaState : uint8_t { None, Running, Restarting };

static const char* link_name(LinkState l) {
  switch (l) {
    case LinkState::Joining: return "joining";
    case LinkState::NoWifi: return "no-wifi";
    case LinkState::Searching: return "searching";
    case LinkState::Unreachable: return "unreachable";
    case LinkState::Up: return "up";
  }
  return "?";
}

